bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
docker inspect "$cid" --format 'state={{.State.Status}} restarts={{.RestartCount}} image={{.Image}} tag={{.Config.Image}}'
docker exec -i -w /opt/videobot "$cid" node --input-type=module - <<'JS'
import pg from 'pg';
import {readFileSync} from 'node:fs';
const p=new pg.Pool({host:process.env.VIDEOBOT_DB_HOST,user:process.env.VIDEOBOT_DB_USER,database:process.env.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:5000});
const c=await p.connect();
try {
 await c.query('BEGIN READ ONLY');
 const q=async(label,sql,params=[])=>{const r=await c.query(sql,params);console.log(label+' '+JSON.stringify(r.rows));};
 console.log('TERMS_CONFIGURED='+Boolean(process.env.CREATEVDOBOT_TERMS_URL));console.log('INVOICE_MODE='+ (process.env.VIDEO_SALE_MODE==='invoice'));
 await q('MASTER_SESSION',"SELECT revision,state->>'screen' AS screen,state->>'publishing' AS publishing,state->'pendingVideoDraft'->>'revision' AS pending_revision, state->'pendingVideoDraft' IS NOT NULL AS pending, state->'draft'->>'mode' AS draft_mode,updated_at FROM videobot_creator_sessions WHERE owner_user_id=$1",[788044853]);
 await q('MASTER_RECENT_LISTINGS',`SELECT left(md5(l.listing_id),10) AS ref,l.status,l.revision,l.created_at,l.updated_at,l.second_thumbnail_file_id IS NOT NULL AS two_thumbnails,l.sample_duration_seconds,l.fee_terms_accepted_at IS NOT NULL AS terms_accepted,(SELECT count(*) FROM videobot_post_receipts r WHERE r.listing_id=l.listing_id) AS receipts,(SELECT count(*) FROM videobot_post_receipts r WHERE r.listing_id=l.listing_id AND r.status='sent') AS sent_receipts FROM videobot_listings l WHERE seller_user_id=$1 ORDER BY created_at DESC LIMIT 15`,[788044853]);
 await q('MASTER_RECEIPTS',`SELECT left(md5(r.listing_id),10) AS ref,r.revision,r.status,r.sale_mode,cardinality(r.free_message_ids) AS free_count,r.paid_message_id IS NOT NULL AS offer_recorded FROM videobot_post_receipts r JOIN videobot_listings l ON l.listing_id=r.listing_id WHERE l.seller_user_id=$1 ORDER BY l.created_at DESC,r.revision DESC LIMIT 20`,[788044853]);
 await q('OWNER_QUEUE', "SELECT status, count(*)::int AS n FROM videobot_owner_update_jobs WHERE owner_id=$1 GROUP BY status",[788044853]);
 await q('RECENT_OWNER_EVENTS',`SELECT j.update_id,j.status,j.job_kind,j.created_at,j.updated_at,CASE WHEN j.payload->'callback_query'->>'data' ~ '^(review:|entry:|menu:)' THEN split_part(j.payload->'callback_query'->>'data','|',1) ELSE 'other' END AS action,w.status AS receipt_status FROM videobot_owner_update_jobs j LEFT JOIN videobot_webhook_updates w USING(update_id) WHERE j.owner_id=$1 ORDER BY j.update_id DESC LIMIT 30`,[788044853]);
 await c.query('ROLLBACK');
}finally{c.release();await p.end()}
JS
docker logs --since 3h "$cid" 2>&1 | grep -E 'Error:|READY=|CREATOR_.*(QUARANTIN|FAIL|ERROR|RECONCIL)' | sed -E 's/[0-9]{6,}:[A-Za-z0-9_-]{20,}/[REDACTED]/g' | cut -c1-200 | tail -n 40 || true
